import{_ as t,a0 as l,w as r,s as o,I as n,x as a,a1 as i,A as p,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"用一個開源工具實現多線程 Python 程序的可視化 | LCTT x X-CMD","titleTemplate":false,"description":"用一個開源工具實現多線程 Python 程序的可視化 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用一個開源工具實現多線程 Python 程序的可視化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用一個開源工具實現多線程 Python 程序的可視化 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210312 Visualize multi-threaded Python programs with an open source tool","title":"用一個開源工具實現多線程 Python 程序的可視化","tag":"202103","desc":""},"relativePath":"202103/20210312 Visualize multi-threaded Python programs with an open source tool.md","filePath":"[post].md"}'),c={name:"202103/20210312 Visualize multi-threaded Python programs with an open source tool.md"};function g(h,s,u,m,k,f){const e=l("Link");return r(),o("div",null,[s[31]||(s[31]=n("h1",{id:"用一個開源工具實現多線程-python-程序的可視化",tabindex:"-1"},[a("用一個開源工具實現多線程 Python 程序的可視化 "),n("a",{class:"header-anchor",href:"#用一個開源工具實現多線程-python-程序的可視化","aria-label":"Permalink to “用一個開源工具實現多線程 Python 程序的可視化”"},"​")],-1)),s[32]||(s[32]=n("blockquote",null,[n("p",null,"VizTracer 可以跟蹤併發的 Python 程序，以幫助記錄、調試和剖析。")],-1)),s[33]||(s[33]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202103/30/230404xi9pox38ookk8xe2.jpg",alt:""})],-1)),s[34]||(s[34]=n("p",null,"併發是現代編程中必不可少的一部分，因為我們有多個核心，有許多需要協作的任務。然而，當併發程序不按順序運行時，就很難理解它們。對於工程師來説，在這些程序中發現 bug 和性能問題不像在單線程、單任務程序中那麼容易。",-1)),n("p",null,[s[1]||(s[1]=a("在 Python 中，你有多種併發的選擇。最常見的可能是用 ",-1)),s[2]||(s[2]=n("code",null,"threading",-1)),s[3]||(s[3]=a(" 模組的多線程，用",-1)),s[4]||(s[4]=n("code",null,"subprocess",-1)),s[5]||(s[5]=a(" 和 ",-1)),s[6]||(s[6]=n("code",null,"multiprocessing",-1)),s[7]||(s[7]=a(" 模組的多進程，以及最近用 ",-1)),s[8]||(s[8]=n("code",null,"asyncio",-1)),s[9]||(s[9]=a(" 模組提供的 ",-1)),s[10]||(s[10]=n("code",null,"async",-1)),s[11]||(s[11]=a(" 語法。在 ",-1)),i(e,{href:"https://readthedocs.org/projects/viztracer/"},{default:p(()=>[...s[0]||(s[0]=[a("VizTracer",-1)])]),_:1}),s[12]||(s[12]=a(" 之前，缺乏分析使用了這些技術程序的工具。",-1))]),s[35]||(s[35]=d(`<p>VizTracer 是一個追蹤和可視化 Python 程序的工具，對日誌、調試和剖析很有幫助。儘管它對單線程、單任務程序很好用，但它在併發程序中的實用性是它的獨特之處。</p><h3 id="嘗試一個簡單的任務" tabindex="-1">嘗試一個簡單的任務 <a class="header-anchor" href="#嘗試一個簡單的任務" aria-label="Permalink to “嘗試一個簡單的任務”">​</a></h3><p>從一個簡單的練習任務開始：計算出一個數組中的整數是否是質數並返回一個布爾數組。下面是一個簡單的解決方案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def is_prime(n):</span></span>
<span class="line"><span>    for i in range(2, n):</span></span>
<span class="line"><span>        if n % i == 0:</span></span>
<span class="line"><span>            return False</span></span>
<span class="line"><span>    return True</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def get_prime_arr(arr):</span></span>
<span class="line"><span>    return [is_prime(elem) for elem in arr]</span></span></code></pre></div><p>試着用 VizTracer 以單線程方式正常運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    num_arr = [random.randint(100, 10000) for _ in range(6000)]</span></span>
<span class="line"><span>    get_prime_arr(num_arr)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>viztracer my_program.py</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_singlethreadtask.png" alt="Running code in a single thread" title="Running code in a single thread"></p><p>調用堆棧報告顯示，耗時約 140ms，大部分時間花在 <code>get_prime_arr</code> 上。</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_callstackreport.png" alt="call-stack report" title="call-stack report"></p><p>這只是在數組中的元素上一遍又一遍地執行 <code>is_prime</code> 函數。</p><p>這是你所期望的，而且它並不有趣（如果你瞭解 VizTracer 的話）。</p><h3 id="試試多線程程序" tabindex="-1">試試多線程程序 <a class="header-anchor" href="#試試多線程程序" aria-label="Permalink to “試試多線程程序”">​</a></h3><p>試着用多線程程序來做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    num_arr = [random.randint(100, 10000) for i in range(2000)]</span></span>
<span class="line"><span>    thread1 = Thread(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    thread2 = Thread(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    thread3 = Thread(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.start()</span></span>
<span class="line"><span>    thread2.start()</span></span>
<span class="line"><span>    thread3.start()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.join()</span></span>
<span class="line"><span>    thread2.join()</span></span>
<span class="line"><span>    thread3.join()</span></span></code></pre></div><p>為了配合單線程程序的工作負載，這就為三個線程使用了一個 2000 元素的數組，模擬了三個線程共享任務的情況。</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_multithread.png" alt="Multi-thread program" title="Multi-thread program"></p><p>如果你熟悉 Python 的全局解釋器鎖（GIL），就會想到，它不會再快了。由於開銷太大，花了 140ms 多一點的時間。不過，你可以觀察到多線程的併發性：</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_concurrency.png" alt="Concurrency of multiple threads" title="Concurrency of multiple threads"></p><p>當一個線程在工作（執行多個 <code>is_prime</code> 函數）時，另一個線程被凍結了（一個 <code>is_prime</code> 函數）；後來，它們進行了切換。這是由於 GIL 的原因，這也是 Python 沒有真正的多線程的原因。它可以實現併發，但不能實現並行。</p><h3 id="用多進程試試" tabindex="-1">用多進程試試 <a class="header-anchor" href="#用多進程試試" aria-label="Permalink to “用多進程試試”">​</a></h3><p>要想實現並行，辦法就是 <code>multiprocessing</code> 庫。下面是另一個使用 <code>multiprocessing</code> 的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    num_arr = [random.randint(100, 10000) for _ in range(2000)]</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>    p1 = Process(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    p2 = Process(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span>    p3 = Process(target=get_prime_arr, args=(num_arr,))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    p1.start()</span></span>
<span class="line"><span>    p2.start()</span></span>
<span class="line"><span>    p3.start()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    p1.join()</span></span>
<span class="line"><span>    p2.join()</span></span>
<span class="line"><span>    p3.join()</span></span></code></pre></div><p>要使用 VizTracer 運行它，你需要一個額外的參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>viztracer --log_multiprocess my_program.py</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_multithreadrun.png" alt="Running with extra argument" title="Running with extra argument"></p><p>整個程序在 50ms 多一點的時間內完成，實際任務在 50ms 之前完成。程序的速度大概提高了三倍。</p><p>為了和多線程版本進行比較，這裏是多進程版本：</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_comparewithmultiprocess.png" alt="Multi-process version" title="Multi-process version"></p><p>在沒有 GIL 的情況下，多個進程可以實現並行，也就是多個 <code>is_prime</code> 函數可以並行執行。</p><p>不過，Python 的多線程也不是一無是處。例如，對於計算密集型和 I/O 密集型程序，你可以用睡眠來偽造一個 I/O 綁定的任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def io_task():</span></span>
<span class="line"><span>    time.sleep(0.01)</span></span></code></pre></div><p>在單線程、單任務程序中試試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    for _ in range(3):</span></span>
<span class="line"><span>        io_task()</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/io-bound_singlethread.png" alt="I/O-bound single-thread, single-task program" title="I/O-bound single-thread, single-task program"></p><p>整個程序用了 30ms 左右，沒什麼特別的。</p><p>現在使用多線程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    thread1 = Thread(target=io_task)</span></span>
<span class="line"><span>    thread2 = Thread(target=io_task)</span></span>
<span class="line"><span>    thread3 = Thread(target=io_task)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.start()</span></span>
<span class="line"><span>    thread2.start()</span></span>
<span class="line"><span>    thread3.start()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    thread1.join()</span></span>
<span class="line"><span>    thread2.join()</span></span>
<span class="line"><span>    thread3.join()</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/io-bound_multithread.png" alt="I/O-bound multi-thread program" title="I/O-bound multi-thread program"></p><p>程序耗時 10ms，很明顯三個線程是併發工作的，這提高了整體性能。</p><h3 id="用-asyncio-試試" tabindex="-1">用 asyncio 試試 <a class="header-anchor" href="#用-asyncio-試試" aria-label="Permalink to “用 asyncio 試試”">​</a></h3><p>Python 正在嘗試引入另一個有趣的功能，叫做異步編程。你可以製作一個異步版的任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import asyncio</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async def io_task():</span></span>
<span class="line"><span>    await asyncio.sleep(0.01)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>async def main():</span></span>
<span class="line"><span>    t1 = asyncio.create_task(io_task())</span></span>
<span class="line"><span>    t2 = asyncio.create_task(io_task())</span></span>
<span class="line"><span>    t3 = asyncio.create_task(io_task())</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    await t1</span></span>
<span class="line"><span>    await t2</span></span>
<span class="line"><span>    await t3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    asyncio.run(main())</span></span></code></pre></div><p>由於 <code>asyncio</code> 從字面上看是一個帶有任務的單線程調度器，你可以直接在它上使用 VizTracer：</p><p><img src="https://opensource.com/sites/default/files/uploads/viztracer_asyncio.png" alt="VizTracer with asyncio" title="VizTracer with asyncio"></p><p>依然花了 10ms，但顯示的大部分函數都是底層結構，這可能不是用户感興趣的。為了解決這個問題，可以使用 <code>--log_async</code> 來分離真正的任務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>viztracer --log_async my_program.py</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/log_async.png" alt="Using --log_async to separate tasks" title="Using --log_async to separate tasks"></p><p>現在，用户任務更加清晰了。在大部分時間裏，沒有任務在運行（因為它唯一做的事情就是睡覺）。有趣的部分是這裏：</p><p><img src="https://opensource.com/sites/default/files/uploads/taskcreation.png" alt="Graph of task creation and execution" title="Graph of task creation and execution"></p><p>這顯示了任務的創建和執行時間。Task-1 是 <code>main()</code> 協程，創建了其他任務。Task-2、Task-3、Task-4 執行 <code>io_task</code> 和 <code>sleep</code> 然後等待喚醒。如圖所示，因為是單線程程序，所以任務之間沒有重疊，VizTracer 這樣可視化是為了讓它更容易理解。</p><p>為了讓它更有趣，可以在任務中添加一個 <code>time.sleep</code> 的調用來阻止異步循環：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>async def io_task():</span></span>
<span class="line"><span>    time.sleep(0.01)</span></span>
<span class="line"><span>    await asyncio.sleep(0.01)</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/time.sleep_call.png" alt="time.sleep call" title="time.sleep call"></p><p>程序耗時更長（40ms），任務填補了異步調度器中的空白。</p><p>這個功能對於診斷異步程序的行為和性能問題非常有幫助。</p><h3 id="看看-viztracer-發生了什麼" tabindex="-1">看看 VizTracer 發生了什麼？ <a class="header-anchor" href="#看看-viztracer-發生了什麼" aria-label="Permalink to “看看 VizTracer 發生了什麼？”">​</a></h3><p>通過 VizTracer，你可以在時間軸上查看程序的進展情況，而不是從複雜的日誌中想像。這有助於你更好地理解你的併發程序。</p>`,58)),n("p",null,[s[14]||(s[14]=a("VizTracer 是開源的，在 Apache 2.0 許可證下發布，支持所有常見的操作系統（Linux、macOS 和 Windows）。你可以在 ",-1)),i(e,{href:"https://github.com/gaogaotiantian/viztracer"},{default:p(()=>[...s[13]||(s[13]=[a("VizTracer 的 GitHub 倉庫",-1)])]),_:1}),s[15]||(s[15]=a("中瞭解更多關於它的功能和訪問它的源代碼。",-1))]),s[36]||(s[36]=n("hr",null,null,-1)),n("p",null,[s[17]||(s[17]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/3/python-viztracer"},{default:p(()=>[...s[16]||(s[16]=[a("https://opensource.com/article/21/3/python-viztracer",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/gaogaotiantian"},{default:p(()=>[...s[18]||(s[18]=[a("Tian Gao",-1)])]),_:1}),s[23]||(s[23]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[19]||(s[19]=[a("lujun9972",-1)])]),_:1}),s[24]||(s[24]=a(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[20]||(s[20]=[a("wxy",-1)])]),_:1}),s[25]||(s[25]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[21]||(s[21]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[28]||(s[28]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[26]||(s[26]=[a("LCTT",-1)])]),_:1}),s[29]||(s[29]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[27]||(s[27]=[a("Linux中國",-1)])]),_:1}),s[30]||(s[30]=a(" 榮譽推出",-1))])])}const T=t(c,[["render",g]]);export{_ as __pageData,T as default};
